    "first_seen_at": "2026-10-11T11:50:10.435Z",
    "update_batch": "morning",
    "image_url": "https://goobjoog.s3.eu-central-1.amazonaws.com/content/uploads/2026/10/11091246/IMG-20261011-WA0003.jpg",
    "featured": false,
